    enroll(userId: string, passcode: string): boolean {
        this.validateUserId(userId);
        this.validatePasscode(passcode);
        if (this.entries.has(userId)) {
            return false;
        }
        this.entries.set(userId, passcode);
        return true;
    }

    authenticate(userId: string, passcode: string): boolean {
        this.validateUserId(userId);
        this.validatePasscode(passcode);
        return this.entries.has(userId);
    }

    remove(userId: string): boolean {
        this.validateUserId(userId);
        return this.entries.delete(userId);
    }

    listUserIds(): string[] {
        return Array.from(this.entries.keys()).sort((a, b) => a.localeCompare(b));
    }

    private validateUserId(userId: string): void {
        if (typeof userId !== "string" || userId.trim().length === 0) {
            throw new TypeError("userId must contain a non-whitespace character");
        }
    }

    private validatePasscode(passcode: string): void {
        if (typeof passcode !== "string" || passcode.length < 4) {
            throw new TypeError("passcode must contain at least four characters");
        }
    }
}

