import { AccessDirectory } from "./solution";

function assert(condition: boolean, message: string): void {
    if (!condition) throw new Error(message);
}

function equal<T>(actual: T, expected: T, message: string): void {
    assert(Object.is(actual, expected), `${message}: expected ${String(expected)}, got ${String(actual)}`);
}

function arrayEqual(actual: readonly string[], expected: readonly string[], message: string): void {
    assert(actual.length === expected.length && actual.every((value, i) => value === expected[i]), message);
}

function throwsTypeError(action: () => unknown, message: string): void {
    let error: unknown;
    try { action(); } catch (caught) { error = caught; }
    assert(error instanceof TypeError, message);
}

const directory = new AccessDirectory();
const firstEmpty = directory.listUserIds();
const secondEmpty = directory.listUserIds();
arrayEqual(firstEmpty, [], "new directory is empty");
assert(firstEmpty !== secondEmpty, "empty lists are fresh arrays");

equal(directory.enroll("alice", "1234"), true, "enrolls a valid user");
equal(directory.enroll("alice", "changed"), false, "duplicate exact ID is rejected");
equal(directory.authenticate("alice", "1234"), true, "original credentials remain after duplicate enrollment");
equal(directory.authenticate("alice", "changed"), false, "duplicate enrollment does not replace passcode");
equal(directory.authenticate("missing", "1234"), false, "unknown user does not authenticate");

equal(directory.enroll(" Alice ", "    "), true, "IDs and passcodes are stored exactly");
equal(directory.enroll("bob", "abcd"), true, "enrolls another user");
const listed = directory.listUserIds();
arrayEqual(listed, [" Alice ", "alice", "bob"], "IDs use ascending exact lexicographic order");
listed.splice(0, listed.length, "corrupt");
arrayEqual(directory.listUserIds(), [" Alice ", "alice", "bob"], "returned list cannot mutate directory");

equal(directory.remove("alice"), true, "remove reports existing entry");
equal(directory.remove("alice"), false, "remove reports missing entry");
equal(directory.authenticate("alice", "1234"), false, "removed user no longer authenticates");

for (const invalidId of ["", " ", "\t\n"]) {
    throwsTypeError(() => directory.enroll(invalidId, "1234"), "enroll rejects invalid ID");
    throwsTypeError(() => directory.authenticate(invalidId, "1234"), "authenticate rejects invalid ID");
    throwsTypeError(() => directory.remove(invalidId), "remove rejects invalid ID");
}
for (const invalidPasscode of ["", "1", "123"]) {
    throwsTypeError(() => directory.enroll("valid", invalidPasscode), "enroll rejects short passcode");
    throwsTypeError(() => directory.authenticate("valid", invalidPasscode), "authenticate rejects short passcode");
}
throwsTypeError(() => directory.enroll(7 as unknown as string, "1234"), "enroll rejects non-string ID");
throwsTypeError(() => directory.authenticate("bob", null as unknown as string), "authenticate rejects non-string passcode");
arrayEqual(directory.listUserIds(), [" Alice ", "bob"], "failed operations do not mutate entries");

